import Foundation
import Testing
import TranscriberCore
@testable import SpeechDetection

/// Cases generated by Tools/parity/make_segmenter_fixture.py, which runs the
/// original `get_speech_timestamps_onnx` on the same probabilities.
struct SpeechSegmenterTests {
    @Test(arguments: try SegmenterFixture.load().cases)
    func matchesOriginalSegmenter(_ testCase: SegmenterFixture.Case) {
        let spans = SpeechSegmenter.speechSpans(in: testCase.probabilities, settings: testCase.settings.vadSettings)
        let expected = testCase.expectedSpans.map {
            SpeechSpan(start: AudioTime(samples: $0.start), end: AudioTime(samples: $0.end))
        }
        #expect(spans == expected, "\(testCase.name)")
    }

    @Test func emptyInputHasNoSpeech() {
        #expect(SpeechSegmenter.speechSpans(in: [], settings: ChickenRiceDefaults.vad).isEmpty)
    }
}

struct SegmenterFixture: Decodable {
    struct Case: Decodable, Sendable, CustomTestStringConvertible {
        let name: String
        let settings: Settings
        let probabilities: [Float]
        let expectedSpans: [SampleSpan]

        var testDescription: String { name }
    }

    struct Settings: Decodable, Sendable {
        let threshold: Double
        let negThreshold: Double?
        let minSpeechDurationMs: Int
        let maxSpeechDurationS: Double?
        let minSilenceDurationMs: Int
        let speechPadMs: Int

        var vadSettings: VADSettings {
            VADSettings(
                threshold: threshold,
                negativeThreshold: negThreshold,
                minimumSpeechDuration: AudioTime(milliseconds: minSpeechDurationMs),
                maximumSpeechDuration: maxSpeechDurationS.map { AudioTime(seconds: $0) },
                minimumSilenceDuration: AudioTime(milliseconds: minSilenceDurationMs),
                speechPadding: AudioTime(milliseconds: speechPadMs)
            )
        }
    }

    struct SampleSpan: Decodable, Sendable {
        let start: Int
        let end: Int
    }

    let cases: [Case]

    static func load() throws -> SegmenterFixture {
        let url = try #require(Bundle.module.url(forResource: "segmenter-cases", withExtension: "json", subdirectory: "Fixtures"))
        let decoder = JSONDecoder()
        decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(SegmenterFixture.self, from: Data(contentsOf: url))
    }
}
